select p.proname, md5(p.prosrc) as md5 from pg_catalog.pg_proc p join pg_catalog.pg_namespace n on n.oid = p.pronamespace where (n.nspname, p.proname) in (('public', 'set_session_price'), ('public', 'record_appointment_settlement'), ('public', 'edit_client_pinned_note'), ('public', 'audit_pinned_note_delete'), ('public', 'audit_client_pricing_change')) order by p.proname, md5(p.prosrc)